def draw_bars(pairs, scale):
    for name, value in pairs:
        ticks = value // scale
        print('%-8s | %s %d' % (name, '#' * ticks, value))

draw_bars([('Critical', 5), ('High', 18), ('Medium', 42), ('Low', 15)], 3)

